<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { supabase } from '@/lib/supabase';
import { removeProduct, saveProduct, listProducts, type ProductInput, type StoreProduct } from '@/services/products';
const router=useRouter(); const products=ref<StoreProduct[]>([]); const loading=ref(true); const saving=ref(false); const notice=ref(''); const error=ref(''); const editorOpen=ref(false); const editingId=ref<string|null>(null); const search=ref('');
const blank=():ProductInput=>({slug:'',name:'',description:'',category:'gemstone',price_lkr:0,price_usd:0,stock_quantity:0,image_url:'',is_published:false});
const form=reactive<ProductInput>(blank());
const filtered=computed(()=>products.value.filter(p=>`${p.name} ${p.slug}`.toLowerCase().includes(search.value.toLowerCase().trim())));
const published=computed(()=>products.value.filter(p=>p.is_published).length);const inventory=computed(()=>products.value.reduce((n,p)=>n+p.stock_quantity,0));
async function refresh(){loading.value=true;error.value='';try{products.value=await listProducts(true)}catch(e){error.value=e instanceof Error?e.message:'Could not load products.'}finally{loading.value=false}}
function create(){editingId.value=null;Object.assign(form,blank());editorOpen.value=true;error.value=''}
function edit(item:StoreProduct){editingId.value=item.id;Object.assign(form,{slug:item.slug,name:item.name,description:item.description,category:item.category,price_lkr:item.price_lkr,price_usd:item.price_usd,stock_quantity:item.stock_quantity,image_url:item.image_url,is_published:item.is_published});editorOpen.value=true;error.value=''}
async function submit(){error.value='';notice.value='';if(!/^https:\/\//.test(form.image_url)){error.value='Use a secure https image URL.';return} saving.value=true;try{const payload={...form,slug:form.slug.trim().toLowerCase().replace(/\s+/g,'-'),name:form.name.trim(),description:form.description.trim()};await saveProduct(payload,editingId.value??undefined);editorOpen.value=false;notice.value=editingId.value?'Product updated.':'Product created.';await refresh()}catch(e){error.value=e instanceof Error?e.message:'Could not save product.'}finally{saving.value=false}}
async function deleteProduct(item:StoreProduct){if(!window.confirm(`Delete “${item.name}”? This cannot be undone.`))return;error.value='';notice.value='';try{await removeProduct(item.id);notice.value='Product deleted.';await refresh()}catch(e){error.value=e instanceof Error?e.message:'Could not delete product.'}}
async function logout(){await supabase?.auth.signOut();await router.replace('/admin/login')}
onMounted(refresh);
</script>
<template><main class="admin-shell"><aside class="sidebar"><RouterLink to="/" class="admin-brand"><span>E</span> EVORYN</RouterLink><p class="side-caption">STUDIO</p><RouterLink to="/admin" class="side-link active">◫ &nbsp; Overview</RouterLink><RouterLink to="/shop" class="side-link">↗ &nbsp; View storefront</RouterLink><div class="side-bottom"><p>PRIVATE ADMIN SPACE</p><button @click="logout">Sign out ↗</button></div></aside><section class="admin-main"><header class="admin-top"><div><p class="crumb">EVORYN / STUDIO</p><h1>Collection overview</h1></div><div class="top-actions"><span class="secure-mark">● &nbsp; Secure session</span><button class="gold-button" @click="create">＋ Add a piece</button></div></header><div v-if="notice" class="toast">{{notice}}</div><div v-if="error&&!editorOpen" class="alert">{{error}} <button @click="refresh">Retry</button></div><div class="stat-grid"><article><span>ALL PIECES</span><strong>{{products.length}}</strong><small>In your catalog</small></article><article><span>LIVE ON STOREFRONT</span><strong>{{published}}</strong><small>Visible to shoppers</small></article><article><span>AVAILABLE UNITS</span><strong>{{inventory}}</strong><small>Across your collection</small></article></div><section class="catalog-panel"><div class="panel-heading"><div><p class="crumb">PRODUCT MANAGEMENT</p><h2>Your collection</h2></div><label class="table-search"><span>⌕</span><input v-model="search" placeholder="Search pieces" aria-label="Search products"/></label></div><div class="table-scroll"><table><thead><tr><th>PIECE</th><th>TYPE</th><th>PRICE · LKR</th><th>STOCK</th><th>STATUS</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="empty-row">Loading your catalog…</td></tr><tr v-else-if="!filtered.length"><td colspan="6" class="empty-row">No products yet. Add your first piece to start the collection.</td></tr><tr v-for="item in filtered" :key="item.id"><td><div class="piece-cell"><img :src="item.image_url" :alt="''"/><div><strong>{{item.name}}</strong><small>/{{item.slug}}</small></div></div></td><td>{{item.category==='gemstone'?'Gemstone':'Jewellery'}}</td><td>{{new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR',maximumFractionDigits:0}).format(item.price_lkr)}}</td><td>{{item.stock_quantity}}</td><td><span :class="item.is_published?'status-live':'status-draft'">{{item.is_published?'Published':'Draft'}}</span></td><td><div class="row-actions"><button :aria-label="`Edit ${item.name}`" @click="edit(item)">Edit</button><button class="delete" :aria-label="`Delete ${item.name}`" @click="deleteProduct(item)">Delete</button></div></td></tr></tbody></table></div></section><p class="footnote">Catalog changes are protected by Supabase row-level security. Never share an admin sign-in.</p></section>
<div v-if="editorOpen" class="modal-backdrop" @click.self="editorOpen=false"><form class="editor" @submit.prevent="submit"><div class="editor-head"><div><p class="crumb">{{editingId?'EDIT PIECE':'NEW PIECE'}}</p><h2>{{editingId?'Refine the details':'Add to the collection'}}</h2></div><button type="button" class="close" aria-label="Close editor" @click="editorOpen=false">×</button></div><div class="form-grid"><label class="span-two">Piece name<input v-model="form.name" required maxlength="160" placeholder="Ceylon blue sapphire"/></label><label>URL slug<input v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="ceylon-blue-sapphire"/></label><label>Category<select v-model="form.category"><option value="gemstone">Gemstone</option><option value="jewellery">Jewellery</option></select></label><label>Price · LKR<input v-model.number="form.price_lkr" type="number" min="0" step="0.01" required/></label><label>Price · USD<input v-model.number="form.price_usd" type="number" min="0" step="0.01" required/></label><label>Available units<input v-model.number="form.stock_quantity" type="number" min="0" step="1" required/></label><label>Image URL<input v-model="form.image_url" type="url" required placeholder="https://…"/></label><label class="span-two">Story / description<textarea v-model="form.description" maxlength="4000" rows="4" placeholder="What makes this piece special?"/></label><label class="publish-toggle span-two"><input v-model="form.is_published" type="checkbox"/> Publish this piece on the storefront</label></div><p v-if="error" class="alert">{{error}}</p><div class="editor-actions"><button type="button" class="cancel" @click="editorOpen=false">Cancel</button><button class="gold-button" :disabled="saving">{{saving?'Saving…':'Save piece'}}</button></div></form></div></main></template>
<style scoped>
