22px,4vw,38px);box-shadow:0 20px 80px #0005}.editor-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:23px}.close{border:0;background:none;font-size:28px;color:#74613d;cursor:pointer}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.form-grid label{display:block;color:#777064;font:9px Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase}.form-grid input:not([type=checkbox]),.form-grid select,.form-grid textarea{width:100%;margin-top:7px;padding:11px;border:1px solid #ded9ce;background:white;color:#2c2924;outline-color:#b99755;font:12px Arial,sans-serif}.span-two{grid-column:1/-1}.publish-toggle{display:flex!important;align-items:center;gap:9px;color:#49453d!important}.publish-toggle input{accent-color:#b99755}.editor-actions{display:flex;justify-content:flex-end;gap:11px;margin-top:20px}.cancel{border:1px solid #d8d2c6;background:none;padding:12px 16px;color:#5b554b;cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:900px){.admin-shell{grid-template-columns:1fr}.sidebar{min-height:0;padding:15px 20px;display:grid;grid-template-columns:1fr auto;align-items:center}.side-caption,.side-link,.side-bottom{display:none}.admin-main{padding-top:25px}.stat-grid{gap:9px}.stat-grid article{padding:16px}.stat-grid strong{font-size:31px}}@media(max-width:600px){.admin-top{align-items:flex-start;flex-direction:column}.top-actions{width:100%;justify-content:space-between}.stat-grid{grid-template-columns:1fr}.stat-grid article{display:grid;grid-template-columns:1fr auto;align-items:center}.stat-grid article strong{grid-row:span 2;margin:0}.panel-heading{align-items:flex-start;flex-direction:column}.table-search{width:100%}.form-grid{grid-template-columns:1fr}.span-two{grid-column:auto}}
